with d as (select value r from jsonb_array_elements($q$[{"notes":["Make the pavlova base up to 2 days ahead and store in an airtight container. Assemble just before serving so the ice cream melts into the warm berries.","If you can't get hokey pokey ice cream, vanilla works fine, drizzle with toffee or caramel sauce for that honeycomb sweetness.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"a2f2d54c-8a5c-43ce-9009-9f478b6cd9af"},{"notes":["Make the rice ahead: cook it the morning of, cool it completely before mixing with the mince so the meatballs hold their shape.","Freeze unbaked meatballs on a tray, then transfer to a container. Cook from frozen, adding a few extra minutes to the simmering time.","This broth is just as good the next day, it tastes even better as the flavours settle overnight.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"In a bowl, combine the lamb mince, cooled rice, half the diced onion, half the garlic, cumin, coriander, and a pinch of salt and pepper. Mix gently until just combined, don't overwork it. Form into 12 meatballs, about the size of walnuts."},{"text":"Heat the oil in a large pot over medium heat. Working in batches, brown the meatballs on all sides, about 8 minutes total. Transfer to a plate."},{"text":"In the same pot, add the remaining onion and garlic. Cook, stirring, until softened and fragrant, about 3 minutes. Stir in the tomato paste and cook for 1 minute."},{"text":"Add the crushed tomatoes and stock. Bring to a gentle simmer until bubbling, stirring to scrape up any browned bits from the bottom of the pot."},{"text":"Return the meatballs to the pot, nestling them into the broth. Reduce heat to low, cover, and simmer for 25 minutes, until the meatballs are cooked through and the broth has thickened slightly."},{"text":"Taste and adjust seasoning with salt and pepper. Serve hot in bowls with the broth, garnished with fresh coriander if you like."}],"id":"c9d6010a-1b7e-4e39-8934-63e01aff8557"},{"notes":["If you can't find fernbrake (gosari), use the same amount of fresh spinach added at the very end, or skip it entirely.","Make ahead: simmer the beef with the stock up to step 5, then cool and refrigerate. Reheat gently and add the vegetables fresh when serving.","Use a good beef stock, homemade or from the butcher makes a real difference. Store-bought is fine, but taste it first as some are very salty.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Place the sliced beef in a large bowl and sprinkle with 1½ tsp salt. Toss to coat evenly. Let it sit for exactly 10 minutes, this draws out the juices and seasons the meat deeply."},{"text":"Add the soy sauce, gochugaru, minced garlic and sesame oil to the beef. Mix well and let sit for another 2 minutes."},{"text":"Heat a large pot or Korean stew pot (galbijjim or ttukbaegi) over medium-high heat. Add the beef mixture and stir-fry for 2 minutes until the meat begins to brown and release its juices."},{"text":"Pour in the stock and bring to a boil, about 5 minutes. Skim any foam that rises to the surface."},{"text":"Add the carrot and fernbrake (if using), and simmer for 8 minutes until the carrot is just tender."},{"text":"Add the bean sprouts and green onion, and simmer for 2 more minutes, until the sprouts are wilted but still crisp. Taste and adjust with the extra ½ tsp salt if needed, it should taste savoury and bold."},{"text":"Divide into bowls and top each with sesame seeds. Serve hot with steamed rice."}],"id":"a7245520-d411-4325-8de8-a5a355f5c37c"},{"steps":[{"text":"Wash the beetroot well, leave the skins on, and place in a large pot of cold water. Bring to a boil, then reduce heat and simmer for 25–30 minutes, until tender when pierced with a fork but still firm, this takes longer than you might think, but it matters because the inside cooks gently and stays sweet."},{"text":"While the beetroot cooks, toast the sesame seeds in a dry frying pan over medium heat, stirring constantly, for 2–3 minutes until golden and fragrant. Tip onto a plate to cool."},{"text":"Toast the walnuts in the same pan, stirring, for about 2 minutes. Set aside to cool."},{"text":"When the beetroot is tender, drain well and let it cool enough to handle, about 5 minutes. Rub off the skins under cold running water, they'll slip off easily, then cut into chunks about 2 cm across."},{"text":"In a small bowl, whisk together the pomegranate molasses, olive oil, lemon juice, minced garlic, salt and pepper."},{"text":"Place the warm beetroot in a serving bowl, pour the dressing over it, and toss gently. Let it sit for 5 minutes so the flavours meld."},{"text":"Just before serving, scatter the toasted sesame seeds and walnuts over the top, and garnish with fresh parsley if you like. The seeds stay crisp this way, you understand why when you taste them."}],"id":"e00cce32-bc0f-46d6-abea-33eaa66ca732"},{"notes":["Make the paste up to a day ahead and store in the fridge, covered. It also freezes well.","Any firm white fish works: barramundi, snapper, flathead or jewfish. Whole is best for flavour and drama, but you can use 800 g of thick fillets instead.","Don't have makrut lime leaves? Use a squeeze of fresh lime juice in the curry instead.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part. Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"steps":[{"text":"Make the curry paste: toast the coriander and cumin seeds in a dry frying pan over medium heat until fragrant, about 2 minutes, then grind in a mortar or spice grinder. Pound the red chillies, ground spices, garlic, shrimp paste, fish sauce and palm sugar together in a mortar until a rough paste forms. Add the neutral oil and stir to combine."},{"text":"Heat 2 tbsp neutral oil in a large saucepan or wok over medium-high heat. Add the curry paste and cook, stirring, until fragrant and darkened slightly, about 3 minutes."},{"text":"Pour in the coconut milk and fish stock, stirring to combine. Bring to a gentle simmer until small bubbles break the surface and the curry is lightly thickened."},{"text":"Carefully lay the whole fish into the simmering curry. The liquid should come partway up the sides of the fish. Tear in the makrut lime leaves and add the fish sauce and palm sugar."},{"text":"Simmer gently for 15–20 minutes, spooning the curry occasionally over the top of the fish, until the fish is cooked through (the flesh should flake easily and be opaque at the thickest point near the backbone)."},{"text":"Taste and adjust the seasoning with fish sauce, palm sugar or lime juice as needed. Scatter fresh Thai basil and sliced chillies over the top and serve with jasmine rice."}],"id":"d01db0ba-d677-47f5-b53e-83b99d29a7f3"},{"notes":["If you can't get rabbit, this works just as well with chicken thighs, they're tougher and hold up to long cooking like rabbit does.","Make it a day ahead; the flavours deepen overnight and it reheats beautifully.","Camp oven tip: bed the pot in hot coals and place coals on the lid for even heat, aim for about 150°C equivalent."],"steps":[{"text":"Heat the oil in a camp oven or heavy-based pot over medium-high heat. Season the rabbit pieces with salt and pepper. Brown them in batches, about 3 minutes per side, then set aside."},{"text":"Add the onions to the pot and cook, stirring, until softened and starting to colour, about 5 minutes. Add the garlic and cook for another minute."},{"text":"Return the rabbit to the pot. Pour in the red wine, scraping the bottom to lift any browned bits. Let it bubble for a minute, then add the stock, bay leaf and thyme."},{"text":"Bring to a simmer, then cover and cook low and slow, either in a camp oven over coals, a slow cooker on low for 3 hours, or a covered pot in a 150°C oven for 2 hours."},{"text":"After 1½ hours, add the carrots, potatoes and parsnip. Stir well and return to the heat."},{"text":"Continue cooking until the rabbit is tender and falling from the bone, the veg is soft, and the sauce is rich and glossy, about another hour. Taste and season with salt and pepper."},{"text":"Serve hot, straight from the pot."}],"id":"1f44fef5-977f-4253-916d-0bef601a560c"},{"notes":["Marinate overnight for best flavour, but 2 hours works in a pinch.","No grill? Use a hot cast-iron pan or oven grill, watch it so the skin chars without burning.","Serve with vinegar dipping sauce (sukang with garlic) if you've got it.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Make the marinade: warm the oil in a small bowl and cook the minced garlic for 1 minute until fragrant. Stir in the turmeric, lime juice and fish sauce. Season with salt and pepper to taste."},{"text":"Pat the chicken dry with paper towels. Place in a large bowl and pour the marinade over, turning to coat well. Cover and marinate for at least 2 hours, or overnight if you have time."},{"text":"Heat a grill or grill pan to medium-high heat until hot and sizzling when a drop of water hits it. Lightly oil the grates or pan. Remove the chicken from the marinade (reserve it), shaking off excess."},{"text":"Grill the chicken skin-side down for 6–8 minutes until golden and charred. Turn and cook the other side for another 6–8 minutes, turning occasionally and basting with reserved marinade. The chicken is done when cooked through (75°C inside) and the skin is charred and smoky."},{"text":"Rest the chicken for 3–4 minutes, then transfer to a plate. Squeeze fresh calamansi over if you like, and scatter spring onion on top. Serve hot with rice."}],"id":"6f3b6f90-b78c-4eac-bba8-094944c8711d"},{"notes":["Make ahead: prepare the fish paste up to 4 hours ahead and keep it covered in the fridge. Assemble and steam just before eating.","Can use barramundi, snapper or any firm white fish. Some cooks add egg white to make the paste lighter.","If you can't find banana leaves, use parchment paper parcels and omit the skewer, tie with kitchen string instead.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Pound or mince the fish fillet until very fine and sticky, about 3 minutes by hand or 1 minute in a food processor. Work it until it becomes almost a smooth paste."},{"text":"Mix the tamarind paste with 2 tbsp water. In a bowl, combine the fish paste with the diluted tamarind, coconut milk, palm sugar, garlic, ginger, chillies, spring onions, fish sauce and salt. Mix well with a fork or your hands until the paste is even and aromatic. Taste and adjust salt or tamarind to your liking."},{"text":"Soften the banana leaves by holding them over a gas flame for a few seconds on each side, or dip them briefly in hot water, until they are pliable. Pat dry."},{"text":"Lay one banana leaf square on a clean surface. Spoon about 2 tbsp of the fish paste into the centre. Fold the leaf into a triangle or rectangle parcel, then lay it seam-side down on your work surface. Skewer it with a wooden stick through both layers to keep it sealed. Repeat with the remaining leaves and paste, making 8 parcels."},{"text":"Bring water to a boil in a steamer or a pot with a bamboo steamer basket until steam is rising steadily. Arrange the otak-otak parcels seam-side down in a single layer in the basket, or on a steamer rack standing upright if you prefer (they hold the shape better that way)."},{"text":"Steam for 12 to 15 minutes over boiling water. The otak-otak is ready when the filling is firm and cooked through, the edges should feel set when you press gently, and the banana leaf may brown slightly at the tips."},{"text":"Remove from the steamer and let cool slightly before serving. Serve warm or at room temperature with rice or as a snack on their own."}],"id":"c4e5816e-905b-4fd6-be7d-d5b69385b4d0"},{"notes":["Make it vegetarian by leaving out the prawns and cooking the bottle gourd a few minutes longer until very tender.","Can be made ahead and reheated gently; add the prawns fresh when you reheat so they don't toughen.","Food safety: Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"id":"fb69793a-ef70-4f29-879c-ef7427011c1c"},{"notes":["Fufu is best eaten fresh and hot. If you need to hold it, cover it loosely with foil to keep it warm but not sweating.","You can make fufu ahead and reheat it gently in the microwave with a splash of water, but the texture won't be quite as pillowy.","Green (unripe) plantains are essential, yellow or ripe ones will make it sweet."],"steps":[{"text":"Put the plantain and cassava in a large pot. Cover with cold water and add the salt. Bring to a boil, then reduce the heat and simmer for 20–25 minutes, until both are very soft and you can easily pierce them with a fork."},{"text":"Drain well in a colander, then return to the pot (or transfer to a food processor in batches if using one). Mash or process until smooth and uniform, it should be pale, creamy and hold together."},{"text":"If mashing by hand, use a wooden spoon or potato masher and work in one direction, folding the mixture over itself, until it becomes pillowy. If using a food processor, pulse until you reach a smooth, slightly sticky paste."},{"text":"Serve hot in a mound on a plate, with your favourite soup or stew on the side for dipping."}],"id":"f3e1de16-e371-4cce-9f1c-bb190c70d099"},{"notes":["Ask your fishmonger to scale and gut the flathead for you if you'd prefer. If you can't find flathead, this works beautifully with any other firm white fish of similar size, snapper, bream or barramundi all take to the same gentle treatment.","Serve with something simple: crushed new potatoes, a green salad, or just good bread to soak up the juices.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"8e10b985-9764-4e97-9011-c18f01fc083e"},{"notes":["Make the caramelised onions a day ahead and refrigerate; reheat gently with the finished soup.","Freeze the soup (without parsley garnish) for up to three months. Thaw overnight in the fridge and reheat slowly on the stove."],"id":"e651a657-d739-484a-9a2e-9f59d7e0a6e6"},{"notes":["Kanpyo keeps for months in a cool cupboard. Opened packages store best in an airtight container.","This dish is equally good served cold the next day. The flavour deepens as it sits.","If you can't find kanpyo, this method works beautifully with other dried vegetables, lotus root or burdock, both softened first."],"steps":[{"text":"Soak the kanpyo in warm water for 5 minutes until pliable. Drain and rinse gently under cold water, rubbing between your fingers to remove any dust. Cut into 8 cm lengths."},{"text":"Bring a pot of water to a boil. Add the kanpyo and simmer for 15 to 20 minutes, stirring gently now and then, until the strips are very tender and pale. Drain well."},{"text":"While the kanpyo cooks, bring the dashi to a simmer in another pot until small bubbles rise at the edges. Add the mirin, soy sauce and a pinch of salt. Taste and adjust."},{"text":"When the kanpyo is cool enough to handle, gather 4 to 5 strips together and tie loosely in a bundle using another strip of kanpyo, or a softened kombu strip. Make 6 to 8 bundles."},{"text":"Gently place the bundles into the simmering dashi. Simmer for 10 to 15 minutes, turning once halfway through, until the broth is absorbed and the kanpyo is glossy and tender."},{"text":"Transfer to a serving dish, spooning any remaining broth over the top. Serve warm or at room temperature."}],"id":"0de069fe-90ff-4621-826c-0639a01f92ea"},{"notes":["You can shape these on the skewers several hours ahead and grill just before serving.","Palm sugar gives the traditional caramel edge, but brown sugar works if you can't find it.","The paste is the soul of sate lilit, pounding it by hand rather than processing keeps the texture alive.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Pound the garlic, shallot, galangal, turmeric and chilli to a fine paste in a mortar and pestle. Add the salt."},{"text":"In a bowl, combine the pork mince, spice paste, coconut cream and palm sugar. Mix gently with your hands until just combined."},{"text":"If using lemongrass, trim each stalk to about 15 cm, keeping the white base. Wet your hands and mould about 2 tbsp of meat around the lower part of each stalk, pressing firmly so it sticks. If using skewers, press the meat firmly onto the skewer in a long shape, leaving 5 cm at the bottom clear."},{"text":"Heat a grill pan or barbecue to medium-high until hot enough to sizzle when the skewers touch it."},{"text":"Grill the sate lilit for 12–15 minutes, turning every 3 minutes, until the outside is deeply charred and the meat is cooked through (the juices should run clear)."},{"text":"Let rest for 2 minutes before serving warm with sambal and jasmine rice."}],"id":"4642fea4-3dcc-4148-835c-ef1af27c7312"},{"notes":["Dirty rice keeps well in the fridge for 3 days and reheats gently with a splash of stock if needed.","Can't find andouille? Any spicy smoked sausage will work, but andouille's got that Cajun soul.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large heavy-bottomed pot over medium-high heat. Brown the sausage until the edges caramelize, about 5 minutes. Remove and set aside."},{"text":"In the same pot, brown the chicken liver in batches until cooked through (no pink inside), about 4 minutes. Remove and set aside."},{"text":"Lower the heat to medium. Add the onion, capsicum, and celery, that's your holy trinity, and cook, stirring often, until soft and starting to colour, about 8 minutes."},{"text":"Stir in the garlic and tomato paste, cooking for 1 minute until fragrant."},{"text":"Add the rice, stirring constantly to coat in the oil, for 2 minutes."},{"text":"Pour in the stock, add the cayenne, and bring to a simmer until bubbling. Return the liver and sausage to the pot, stir, and cover."},{"text":"Cook over low heat until the rice is tender and the liquid is absorbed, about 18 minutes. Don't lift the lid."},{"text":"Season with salt and black pepper to taste. Scatter the spring onions over the top before serving."}],"id":"f1775b1f-2cd8-4f80-b14e-02069742844e"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;